// StackDock — Verify Stripe-Signature (whsec_ decoded) + generate SDOCK + Resend JSON
const crypto = require('crypto');

const getEnv = (name) => {
  let v;
  try { v = $env[name]; } catch (e) { v = undefined; }
  if (v === undefined || v === null || v === '') {
    try { v = process.env[name]; } catch (e2) {}
  }
  return v;
};

const item = $input.first().json;
const headers = item.headers || {};
const sigHeader = headers['stripe-signature'] || headers['Stripe-Signature'] || '';
const secret = String(getEnv('STACKDOCK_STRIPE_WEBHOOK_SECRET') || getEnv('STRIPE_WEBHOOK_SECRET') || '').trim();
if (!secret.startsWith('whsec_')) {
  throw new Error('STACKDOCK_STRIPE_WEBHOOK_SECRET missing or invalid (expected whsec_...)');
}
if (!sigHeader) {
  throw new Error('Missing Stripe-Signature header');
}

let rawBody = '';
if (typeof item.rawBody === 'string' && item.rawBody.length) {
  rawBody = item.rawBody;
} else if (Buffer.isBuffer(item.rawBody)) {
  rawBody = item.rawBody.toString('utf8');
} else if ($input.first().binary && $input.first().binary.data) {
  const b = $input.first().binary.data;
  rawBody = Buffer.from(b.data, b.encoding || 'base64').toString('utf8');
} else {
  rawBody = JSON.stringify(item.body ?? item);
}

const parts = Object.fromEntries(
  String(sigHeader).split(',').map((p) => {
    const i = p.indexOf('=');
    return [p.slice(0, i), p.slice(i + 1)];
  })
);
const timestamp = parts.t;
const v1 = parts.v1;
if (!timestamp || !v1) {
  throw new Error('Malformed Stripe-Signature header');
}

const ageSec = Math.abs(Date.now() / 1000 - Number(timestamp));
if (!Number.isFinite(ageSec) || ageSec > 300) {
  throw new Error('Stripe webhook timestamp outside tolerance');
}

const signedPayload = `${timestamp}.${rawBody}`;
const secretKey = Buffer.from(secret.slice(6), 'base64');
const expected = crypto.createHmac('sha256', secretKey).update(signedPayload, 'utf8').digest('hex');
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(String(v1), 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid Stripe signature');
}

let event;
try {
  event = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
} catch (e) {
  throw new Error('Stripe body is not valid JSON');
}

if (event?.type && event.type !== 'checkout.session.completed') {
  return [];
}

const obj = event?.data?.object || {};
const emailRaw = obj?.customer_details?.email || obj?.customer_email || '';
const email = String(emailRaw).trim().toLowerCase();
const emailOk = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(email);
if (!emailOk) {
  throw new Error('No valid customer email in Stripe payload');
}

const escapeHtml = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const pem = String(getEnv('STACKDOCK_PRIVATE_KEY_PEM') || '').replace(/\\n/g, '\n');
if (!pem.includes('PRIVATE KEY')) {
  throw new Error('STACKDOCK_PRIVATE_KEY_PEM missing or invalid');
}

const payload = Buffer.from(`${email}|stackdock-pro|3macs`, 'utf8');
const signature = crypto.sign(null, payload, pem);
const b64url = signature
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/g, '');
const licenseKey = `SDOCK-${b64url}`;

const dmgUrl = getEnv('STACKDOCK_DMG_URL') || 'https://stackdock.iareal.net/download/StackDock-4.0.2.dmg';
const fromEmail = getEnv('STACKDOCK_FROM_EMAIL') || 'stackdock@vibesystems.tech';
const replyTo = getEnv('STACKDOCK_REPLY_TO') || 'stackdock@iareal.net';
const resendKey = String(getEnv('RESEND_API_KEY') || '').trim();
if (!resendKey) {
  throw new Error('RESEND_API_KEY missing in n8n');
}

const safeEmail = escapeHtml(email);
const safeKey = escapeHtml(licenseKey);
const safeDmg = escapeHtml(dmgUrl);

const html = `<!DOCTYPE html><html><body style="margin:0;background:#0b0d10;color:#e8eaed;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif"><div style="max-width:560px;margin:0 auto;padding:40px 24px"><div style="font-size:12px;letter-spacing:0.18em;color:#8b939e;margin-bottom:12px">BLACK EYE</div><h1 style="font-size:28px;font-weight:600;margin:0 0 8px;color:#fff">StackDock Pro</h1><p style="color:#a7b0ba;line-height:1.55;margin:0 0 28px">Pago único activado. Licencia válida hasta en 3 Macs.</p><a href="${safeDmg}" style="display:inline-block;background:#f2f4f7;color:#0b0d10;text-decoration:none;font-weight:600;padding:14px 22px;border-radius:10px;margin-bottom:28px">Descargar StackDock (.dmg)</a><div style="margin-top:28px;padding:18px;border:1px solid #2a3038;border-radius:12px;background:#12161c"><div style="font-size:12px;color:#8b939e;margin-bottom:8px">Correo</div><div style="margin-bottom:16px">${safeEmail}</div><div style="font-size:12px;color:#8b939e;margin-bottom:8px">License Key</div><code style="display:block;word-break:break-all;color:#7dd3fc;font-size:13px">${safeKey}</code></div><p style="color:#6b7380;font-size:12px;margin-top:28px;line-height:1.5">En StackDock: menú → Activar licencia → pega email + clave.</p></div></body></html>`;

const resendPayload = JSON.stringify({
  from: `BLACK EYE <${fromEmail}>`,
  to: [email],
  reply_to: replyTo,
  subject: 'Tu licencia StackDock Pro — BLACK EYE',
  html
});

return [{
  json: {
    email,
    licenseKey,
    dmgUrl,
    product: 'StackDock Pro',
    macs: 3,
    stripeEventId: event.id || null,
    resendKey,
    resendPayload
  }
}];
